#!/usr/bin/env bash
# Rebuild every npm-packed generated byte from the reviewed source tree.

set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)

# dist/ is intentionally gitignored but npm includes it because it contains the
# package exports and binary. Never let pre-existing ignored bytes survive into
# a package: remove the whole tree, then regenerate it from source.
rm -rf -- "$ROOT/dist"
(
  cd "$ROOT"
  npm run build:manifest
)
